//! Outside forwards: what happened to each forwarded message, and the
//! pauses that follow (prd-hostmail-external-forwarding-v1 §3.5, §3.6;
//! vs-live FW-A3, FW-A6, FW-A13, FW-A14; slice FW3).
//!
//! **Where the outcomes come from.** Only the local mail server's delivery
//! webhook ([`crate::email_notify::webhook`]); K2 never reads a person's
//! mailbox for bounces. Per forwarded message:
//!
//! ```text
//!   queue.autogenerated-queued  from = the mailbox, to = the destination  → link queue id → forward, `queued`
//!   delivery.delivered          (queue id, to)                            → `delivered`
//!   delivery.dsn-perm-fail      (queue id, to, details)                   → `refused_user` | `refused_policy` | `failed`
//!   delivery.failed             (queue id, to): retries ran out           → `failed`
//! ```
//!
//! Each outcome is kept once per (queue id, kind), so a batch the mail
//! server sends again changes nothing.
//!
//! **User vs policy refusals (the enhanced status).** Stalwart 0.16.25's
//! `delivery.rcpt-to-rejected` carries only the basic reply code (`550`)
//! and the reply text with the enhanced status code cut out (smtp-proto
//! parses it into a separate field the event doesn't carry). Its
//! `delivery.dsn-perm-fail` carries no `code`, but its `details` is the
//! failure as text, `Unexpected response for RCPT TO:<…>: Code: 550,
//! Enhanced code: 5.1.1, Message: …` (`0.0.0` when the receiver sent
//! none). It fires once for every permanently failed recipient, whatever
//! the DSN settings, so K2 classifies refusals from it alone ([`classify`]):
//! 5.1.x and 5.2.1 are "this address doesn't exist or is disabled", 5.7.x
//! is policy or spam; with no enhanced code the reply text decides
//! ([`refusal_from_text`]); anything else (mailbox full, a 4xx that ran
//! out of retries, a connection failure) is `failed`.
//! `rcpt-to-rejected` is not counted (it would count the same refusal
//! twice, without the enhanced code).
//!
//! **Pauses** (each one through [`forward_sync::pause`], so the mailbox's
//! Sieve goes keep-only at once, and each with a notice):
//!
//! - `dest_gone`, per destination: [`store::DEST_GONE_IN_A_ROW`] "doesn't
//!   exist" refusals in a row (a delivery breaks the run), or those refusals
//!   over Email Notifications' hard-bounce rate
//!   ([`k2_core::email_outcomes::trips`]: over 5% of at least 50);
//! - `refused`, per destination: more than [`store::REFUSED_PCT`]% of the
//!   forwards refused for policy or spam, with at least
//!   [`store::REFUSED_MIN`] forwards. There is no spam-complaint signal for
//!   forwarded mail: a provider's complaint report doesn't reach K2 (it never
//!   reads a mailbox), so these refusals and the stop link stand in for it;
//! - `daily_cap`, per mailbox: [`store::DAILY_CAP`] copies across all its
//!   destinations pause all its outside forwards (the hourly caps are the
//!   mail server's throttles, [`crate::mail::defaults::forward_throttles`],
//!   and count each destination's copy too: each is its own queued message);
//! - `box_brake`: the whole box's outside forwards refused more than
//!   [`store::BRAKE_PCT`]% with at least [`store::BRAKE_MIN`] forwards:
//!   every active outside forward pauses and the owner gets one notice.
//!   Only the owner or an Admin resumes these. If every refusal came from one
//!   mailbox, only that mailbox pauses (`refused`): whoever can get one mailbox
//!   refused can't stop the whole box. (Stalwart's events don't carry the
//!   original sender, so the mailbox is as fine as this can count.)
//!
//! The windows are the last 24 hours, and never earlier than the
//! forward's last start (activation or resume): a resumed forward isn't
//! paused again for what happened before the resume. The brake's window
//! starts again when the owner resumes a forward it paused.
//!
//! **The webhook stays on** while any outside forward is live, even with
//! Email Notifications off ([`webhook_wanted`]).
//!
//! The daemon log carries ids and counts, never an address. Notices (the
//! owner's tickets) name the mailbox and the destination, like the card.

use std::collections::BTreeSet;
use std::sync::Mutex;

use k2_core::mail_forward::{self as store, Counts, Forward};
use rusqlite::{params, Connection, OptionalExtension};
use serde_json::json;

use super::forward_sync;
use crate::email_notify::webhook::HookEvent;

const P: &str = "[mail/forward-outcomes]";

/// The queued event a Sieve redirect makes.
pub const AUTOGEN_QUEUED: &str = "queue.autogenerated-queued";
pub const DELIVERED: &str = "delivery.delivered";
pub const DSN_PERM_FAIL: &str = "delivery.dsn-perm-fail";
pub const FAILED: &str = "delivery.failed";

/// One evaluation at a time (two webhook batches never pause the same
/// forward twice or file two notices for one pause).
static EVAL: Mutex<()> = Mutex::new(());

thread_local! {
    /// This thread holds [`EVAL`]: a pause it makes comes back through
    /// [`after_change`], which must not take the lock again.
    static IN_EVAL: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// [`EVAL`] held, with [`IN_EVAL`] set for as long as it lives.
struct Evaluating(#[allow(dead_code)] std::sync::MutexGuard<'static, ()>);

impl Evaluating {
    fn lock() -> Self {
        let g = EVAL.lock().unwrap_or_else(|e| e.into_inner());
        IN_EVAL.with(|c| c.set(true));
        Evaluating(g)
    }
}

impl Drop for Evaluating {
    fn drop(&mut self) {
        IN_EVAL.with(|c| c.set(false));
    }
}

// ── classifying a refusal (pure) ────────────────────────────────────

/// What a permanent failure's text says: the basic reply code and the
/// enhanced status code (`None` when absent or `0.0.0`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Status {
    pub code: Option<u16>,
    pub enhanced: Option<(u8, u16, u16)>,
}

impl Status {
    /// `550 5.1.1`, `550`, `5.7.1` (kept with the outcome; no address).
    pub fn label(&self) -> Option<String> {
        let esc = self.enhanced.map(|(a, b, c)| format!("{a}.{b}.{c}"));
        match (self.code, esc) {
            (Some(c), Some(e)) => Some(format!("{c} {e}")),
            (Some(c), None) => Some(c.to_string()),
            (None, Some(e)) => Some(e),
            (None, None) => None,
        }
    }
}

fn digits_after(s: &str, at: usize, max: usize) -> Option<(u32, usize)> {
    let tail = &s[at..];
    let n = tail.bytes().take(max).take_while(u8::is_ascii_digit).count();
    if n == 0 {
        return None;
    }
    tail[..n].parse().ok().map(|v| (v, at + n))
}

/// `x.y.z` at `at` (`x` one digit, `y`/`z` up to three).
fn esc_at(s: &str, at: usize) -> Option<(u8, u16, u16)> {
    let (a, i) = digits_after(s, at, 1)?;
    if s.as_bytes().get(i) != Some(&b'.') {
        return None;
    }
    let (b, i) = digits_after(s, i + 1, 3)?;
    if s.as_bytes().get(i) != Some(&b'.') {
        return None;
    }
    let (c, _) = digits_after(s, i + 1, 3)?;
    Some((a as u8, b as u16, c as u16))
}

/// Read the codes out of a failure's text. Stalwart's own form
/// (`Code: 550, Enhanced code: 5.1.1, Message: …`) first; else a raw
/// reply (`550 5.1.1 …` / `550-5.1.1 …`) at the start of the text.
pub fn parse_status(details: &str) -> Status {
    let mut st = Status::default();
    if let Some(i) = details.find("Code: ") {
        st.code = digits_after(details, i + 6, 3).filter(|(_, end)| end - (i + 6) == 3).map(|(v, _)| v as u16);
    }
    if let Some(i) = details.find("Enhanced code: ") {
        st.enhanced = esc_at(details, i + 15).filter(|e| e.0 != 0);
    }
    if st.code.is_none() && st.enhanced.is_none() {
        let t = details.trim_start();
        if let Some((v, end)) = digits_after(t, 0, 3).filter(|(_, end)| *end == 3) {
            st.code = Some(v as u16);
            if matches!(t.as_bytes().get(end), Some(b' ') | Some(b'-')) {
                st.enhanced = esc_at(t, end + 1).filter(|e| e.0 != 0);
            }
        }
    }
    st
}

/// The reply text (after `Message: `), lower case.
fn message_text(details: &str) -> String {
    details.split_once("Message: ").map(|(_, m)| m).unwrap_or(details).to_ascii_lowercase()
}

const USER_WORDS: &[&str] = &[
    "user unknown",
    "unknown user",
    "no such user",
    "user not found",
    "unknown recipient",
    "recipient unknown",
    "no such recipient",
    "recipient not found",
    "invalid recipient",
    "does not exist",
    "doesn't exist",
    "no such mailbox",
    "mailbox not found",
    "mailbox does not exist",
    "mailbox is disabled",
    "mailbox disabled",
    "account disabled",
    "account has been disabled",
    "account is disabled",
    "address not found",
];

const POLICY_WORDS: &[&str] = &[
    "spam",
    "policy",
    "blocked",
    "blocklist",
    "blacklist",
    "block list",
    "black list",
    "dmarc",
    "spf",
    "dkim",
    "reputation",
    "dnsbl",
    "spamhaus",
    "junk",
    "abuse",
];

/// A refusal with no enhanced code: the reply text decides. Policy words
/// win over "doesn't exist" words (a policy refusal must never read as a
/// gone mailbox).
pub fn refusal_from_text(text: &str) -> &'static str {
    let t = text.to_ascii_lowercase();
    if POLICY_WORDS.iter().any(|w| t.contains(w)) {
        store::O_REFUSED_POLICY
    } else if USER_WORDS.iter().any(|w| t.contains(w)) {
        store::O_REFUSED_USER
    } else {
        store::O_FAILED
    }
}

/// The outcome of a permanent failure's text.
pub fn refusal(details: &str) -> (&'static str, Status) {
    let st = parse_status(details);
    let permanent = st.enhanced.map(|e| e.0 == 5).unwrap_or_else(|| st.code.is_some_and(|c| (500..600).contains(&c)));
    let kind = if !permanent {
        // A temporary failure that ran out of retries, a connection or DNS
        // failure, a queue error: not the destination refusing the mail.
        store::O_FAILED
    } else {
        match st.enhanced {
            Some((5, 1, _)) | Some((5, 2, 1)) => store::O_REFUSED_USER,
            Some((5, 7, _)) => store::O_REFUSED_POLICY,
            // Stalwart's own "Mailbox not found" for a domain it hosts is
            // 5.5.0: a generic code, so the text decides.
            Some((5, 5, 0)) => refusal_from_text(&message_text(details)),
            Some(_) => store::O_FAILED,
            None => refusal_from_text(&message_text(details)),
        }
    };
    (kind, st)
}

/// The outcome one webhook event gives a forwarded message, with the code
/// kept beside it (`None`: not an outcome this module counts).
pub fn classify(e: &HookEvent) -> Option<(&'static str, Option<String>)> {
    match e.kind.as_str() {
        DELIVERED => Some((store::O_DELIVERED, e.code.map(|c| c.to_string()))),
        DSN_PERM_FAIL => {
            let (kind, st) = refusal(e.details.as_deref().unwrap_or(""));
            Some((kind, st.label()))
        }
        FAILED => Some((store::O_FAILED, None)),
        _ => None,
    }
}

// ── when to pause (pure) ────────────────────────────────────────────

/// Why one forward's numbers pause it, if they do. `in_a_row`: its
/// "doesn't exist" refusals since the last delivery.
pub fn forward_trip(c: &Counts, in_a_row: i64) -> Option<&'static str> {
    if in_a_row >= store::DEST_GONE_IN_A_ROW || k2_core::email_outcomes::trips(c.queued, c.refused_user, 0).is_some() {
        return Some(store::P_DEST_GONE);
    }
    if c.queued >= store::REFUSED_MIN && c.refused_policy * 100 > store::REFUSED_PCT * c.queued {
        return Some(store::P_REFUSED);
    }
    if c.queued >= store::DAILY_CAP {
        return Some(store::P_DAILY_CAP);
    }
    None
}

/// Do the box's numbers trip the brake?
pub fn brake_trip(c: &Counts) -> bool {
    c.queued >= store::BRAKE_MIN && c.refused() * 100 > store::BRAKE_PCT * c.queued
}

// ── the windows ─────────────────────────────────────────────────────

/// When the forward last started forwarding (activated, or resumed by a person or
/// by K2). An agent's own pause and resume doesn't count: it would wipe the count
/// that pauses a destination that keeps refusing.
pub fn started_at(conn: &Connection, forward_id: &str) -> Result<i64, String> {
    conn.query_row(
        "SELECT COALESCE(MAX(at), 0) FROM mail_forward_events WHERE forward_id = ?1 \
         AND (event = 'activated' OR (event = 'resumed' AND actor NOT LIKE 'agent:%'))",
        params![forward_id],
        |r| r.get(0),
    )
    .map_err(|e| format!("mail forwards: start: {e}"))
}

/// When a forward the brake paused, the whole box's or one mailbox's, was last
/// resumed (0: never): the brake's window starts there. Otherwise a person's
/// resume would trip it again on the same numbers.
pub fn brake_released_at(conn: &Connection) -> Result<i64, String> {
    conn.query_row(
        "SELECT COALESCE(MAX(r.at), 0) FROM mail_forward_events r WHERE r.event = 'resumed' AND (( \
           SELECT p.detail_json FROM mail_forward_events p WHERE p.forward_id = r.forward_id AND p.event = 'paused' \
           AND p.at <= r.at ORDER BY p.at DESC, p.rowid DESC LIMIT 1) GLOB '*\"reason\":\"box_brake\"*' OR ( \
           SELECT p.detail_json FROM mail_forward_events p WHERE p.forward_id = r.forward_id AND p.event = 'paused' \
           AND p.at <= r.at ORDER BY p.at DESC, p.rowid DESC LIMIT 1) GLOB '*\"oneMailbox\":true*')",
        [],
        |r| r.get(0),
    )
    .map_err(|e| format!("mail forwards: brake release: {e}"))
}

/// Has the brake paused anything since `since`?
fn brake_tripped_since(conn: &Connection, since: i64) -> Result<bool, String> {
    conn.query_row(
        "SELECT COUNT(*) FROM mail_forward_events WHERE event = 'paused' AND at >= ?1 AND detail_json LIKE '%\"reason\":\"box_brake\"%'",
        params![since],
        |r| r.get::<_, i64>(0),
    )
    .map(|n| n > 0)
    .map_err(|e| format!("mail forwards: brake trips: {e}"))
}

fn window_start(now: i64, started: i64) -> i64 {
    (now - store::WINDOW_SECS).max(started)
}

// ── the webhook join ────────────────────────────────────────────────

/// What one batch did.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Applied {
    /// New queue id → forward links.
    pub linked: usize,
    /// Outcomes recorded.
    pub recorded: usize,
    /// Forwards paused (with the reason).
    pub paused: Vec<(String, &'static str)>,
}

/// Is any outside forward live (the webhook must stay on)?
pub fn webhook_wanted() -> bool {
    let db = k2_core::db::shared();
    let conn = db.lock();
    conn.query_row("SELECT 1 FROM mail_forwards WHERE dest_kind = 'external' AND state <> 'removed' LIMIT 1", [], |_| Ok(()))
        .optional()
        .map(|o| o.is_some())
        .unwrap_or(false)
}

/// Apply one webhook batch: link, record, then check the pauses.
pub fn apply(events: &[HookEvent], now: i64) -> Applied {
    let mut out = Applied::default();
    if !events.iter().any(|e| e.queue_id.is_some()) {
        return out;
    }
    let mut touched: BTreeSet<String> = BTreeSet::new();
    let mut bounced_notices: Vec<Forward> = Vec::new();
    {
        let db = k2_core::db::shared();
        let conn = db.lock();
        // The live outside forwards (only needed for a queued event).
        let mut live: Option<Vec<Forward>> = None;
        for e in events {
            let Some(qid) = e.queue_id.as_deref() else { continue };
            if e.kind == AUTOGEN_QUEUED {
                let Some(from) = e.from.as_deref().filter(|f| !f.is_empty()) else { continue };
                if live.is_none() {
                    live = Some(store::list(&conn, &store::ListFilter { external_only: true, ..Default::default() }).unwrap_or_default());
                }
                let Some(f) = live.as_ref().and_then(|l| {
                    l.iter().find(|f| f.address.eq_ignore_ascii_case(from) && e.to.iter().any(|t| t.eq_ignore_ascii_case(&f.dest)))
                }) else {
                    continue;
                };
                match store::link_queue(&conn, qid, &f.id, now) {
                    Ok(true) => out.linked += 1,
                    Ok(false) => {}
                    Err(_) => {
                        k2_core::log_debug!("{P} WARN queue {qid} for forward {} wasn't linked", f.id);
                        continue;
                    }
                }
                if let Ok(true) = store::record_outcome(&conn, &f.id, Some(qid), store::O_QUEUED, None, now) {
                    out.recorded += 1;
                    touched.insert(f.id.clone());
                }
                continue;
            }
            let Some((kind, code)) = classify(e) else { continue };
            let Some(fid) = store::forward_for_queue(&conn, qid).ok().flatten() else {
                // Not a forwarded copy. A notice K2 sent from the mailbox itself
                // bouncing lands here: the row can't keep saying `sent`.
                if e.kind == DSN_PERM_FAIL {
                    if let Some(from) = e.from.as_deref() {
                        for to in &e.to {
                            if let Ok(Some(f)) = store::live_for_pair(&conn, &from.to_ascii_lowercase(), &to.to_ascii_lowercase()) {
                                if f.is_external() && f.notice_state.as_deref() == Some(store::N_SENT) && f.notice_at.is_some_and(|t| now - t < store::WINDOW_SECS) {
                                    bounced_notices.push(f);
                                }
                            }
                        }
                    }
                }
                continue;
            };
            let Some(f) = store::get(&conn, &fid).ok().flatten() else { continue };
            // Only the forward's own destination (the message has no other).
            if !e.to.is_empty() && !e.to.iter().any(|t| t.eq_ignore_ascii_case(&f.dest)) {
                continue;
            }
            match store::record_outcome(&conn, &fid, Some(qid), kind, code.as_deref(), now) {
                Ok(true) => {
                    out.recorded += 1;
                    touched.insert(fid);
                }
                Ok(false) => {}
                Err(_) => k2_core::log_debug!("{P} WARN an outcome for forward {fid} wasn't stored"),
            }
        }
    }
    for f in &bounced_notices {
        super::forward_verify::notice_bounced(f, now);
    }
    if touched.is_empty() {
        return out;
    }
    let _g = Evaluating::lock();
    for fid in &touched {
        if let Some(reason) = evaluate_locked(fid, now) {
            out.paused.push((fid.clone(), reason));
        }
    }
    for fid in evaluate_box_locked(now) {
        out.paused.push((fid, store::P_BOX_BRAKE));
    }
    if out.recorded > 0 || !out.paused.is_empty() {
        k2_core::log_debug!("{P} {} linked, {} outcome(s), {} paused", out.linked, out.recorded, out.paused.len());
    }
    out
}

// ── pausing ─────────────────────────────────────────────────────────

/// Check one forward; pause it if its numbers say so. Returns the reason.
pub fn evaluate(forward_id: &str, now: i64) -> Option<&'static str> {
    let _g = Evaluating::lock();
    evaluate_locked(forward_id, now)
}

fn evaluate_locked(forward_id: &str, now: i64) -> Option<&'static str> {
    let (f, c, in_a_row, since, copies, siblings) = {
        let db = k2_core::db::shared();
        let conn = db.lock();
        let f = store::get(&conn, forward_id).ok().flatten()?;
        if !f.is_external() || !f.is_active() {
            return None;
        }
        let since = window_start(now, started_at(&conn, forward_id).ok()?);
        let c = store::counts(&conn, forward_id, since).ok()?;
        let in_a_row = store::user_refusals_in_a_row(&conn, forward_id, since).ok()?;
        // The daily cap is the mailbox's: every destination's copies count, on
        // any row it had in the window, so `rm` and `add` don't start it over.
        let copies = store::mailbox_queued(&conn, &f.address_id, store::daily_window_start(&conn, &f.address_id, now).ok()?).ok()?;
        let siblings: Vec<Forward> = store::live_rows(&conn, &f.address_id)
            .ok()?
            .into_iter()
            .filter(|o| o.id != f.id && o.is_external() && o.is_active())
            .collect();
        (f, c, in_a_row, since, copies, siblings)
    };
    let reason = forward_trip(&c, in_a_row).or((copies >= store::DAILY_CAP).then_some(store::P_DAILY_CAP))?;
    let detail = json!({
        "queued": c.queued, "delivered": c.delivered, "refusedUser": c.refused_user, "refusedPolicy": c.refused_policy,
        "failed": c.failed, "inARow": in_a_row, "since": since, "mailboxCopies": copies,
    });
    let mut note = notice_for(&f, reason, &Counts { queued: if reason == store::P_DAILY_CAP { copies } else { c.queued }, ..c }, in_a_row);
    if reason == store::P_DAILY_CAP && !siblings.is_empty() {
        note.1 = format!("{} (This limit is the mailbox's, so forwarding to all its outside addresses is paused.)", note.1);
    }
    pause_and_tell(&f, reason, detail.clone(), Some(note));
    if reason == store::P_DAILY_CAP {
        for o in &siblings {
            pause_and_tell(o, reason, detail.clone(), None);
        }
    }
    Some(reason)
}

/// Check the whole box; with the brake tripped, pause every active
/// outside forward. Returns the forwards it paused.
pub fn evaluate_box(now: i64) -> Vec<String> {
    let _g = Evaluating::lock();
    evaluate_box_locked(now)
}

fn evaluate_box_locked(now: i64) -> Vec<String> {
    let (c, active, first_trip) = {
        let db = k2_core::db::shared();
        let conn = db.lock();
        let Ok(released) = brake_released_at(&conn) else { return Vec::new() };
        let since = window_start(now, released);
        let Ok(c) = store::box_counts(&conn, since) else { return Vec::new() };
        if !brake_trip(&c) {
            return Vec::new();
        }
        // One mailbox's refusals stop that mailbox, not the whole box. A stray
        // failure or two elsewhere doesn't make it the box's problem. This stops
        // accidents only: someone writing to a few mailboxes on purpose still
        // trips it, because delivery events don't say who sent the original.
        if let Ok([(top, _, _), others @ ..]) = store::refusals_by_mailbox(&conn, since).as_deref() {
            if others.iter().map(|(_, refused, _)| refused).sum::<i64>() < store::BRAKE_OTHER_MAILBOXES_MIN {
                let top = top.clone();
                let rows: Vec<Forward> = store::live_rows(&conn, &top).unwrap_or_default().into_iter().filter(|f| f.is_external() && f.is_active()).collect();
                drop(conn);
                return pause_one_mailbox(&rows, &c);
            }
        }
        let active: Vec<Forward> = store::list(&conn, &store::ListFilter { state: Some(store::ST_ACTIVE), external_only: true, ..Default::default() })
            .unwrap_or_default();
        let first_trip = !brake_tripped_since(&conn, released).unwrap_or(false);
        (c, active, first_trip)
    };
    let detail = json!({ "boxQueued": c.queued, "boxRefused": c.refused(), "boxFailed": c.failed });
    let mut paused = Vec::new();
    for f in &active {
        if pause_and_tell(f, store::P_BOX_BRAKE, detail.clone(), None) {
            paused.push(f.id.clone());
        }
    }
    if !paused.is_empty() {
        k2_core::log_debug!("{P} box brake: {} of {} outside forwards refused in 24 h; {} paused", c.refused(), c.queued, paused.len());
        if first_trip {
            let n = paused.len();
            super::forward_verify::tell_owner(
                "Forwarding to outside addresses is paused on this server",
                &format!(
                    "Receiving servers refused {} of the {} messages this server forwarded to outside addresses in the last 24 hours \
                     (more than {}%). To protect this server's mail reputation, K2 paused all {n} outside forward{}. \
                     New mail stays in each mailbox; nothing is lost.\n\n\
                     Only the owner or an Admin can resume them. See which ones: k2 hostmail forward list --paused. \
                     Resume one: k2 hostmail forward resume <mailbox>. Check what was refused first: \
                     the bounce reports are in each mailbox.",
                    c.refused(),
                    c.queued,
                    store::BRAKE_PCT,
                    if n == 1 { "" } else { "s" },
                ),
                &[],
            );
        }
    }
    paused
}

/// The brake's numbers, but every refusal came from one mailbox: pause its
/// outside forwards, and leave the rest of the box alone.
fn pause_one_mailbox(rows: &[Forward], c: &Counts) -> Vec<String> {
    let detail = json!({ "boxQueued": c.queued, "boxRefused": c.refused(), "boxFailed": c.failed, "oneMailbox": true });
    let mut paused = Vec::new();
    for f in rows {
        if pause_and_tell(f, store::P_REFUSED, detail.clone(), None) {
            paused.push(f.id.clone());
        }
    }
    if let Some(f) = rows.first() {
        super::forward_verify::tell_owner(
            &format!("Forwarding from {} is paused", f.address),
            &format!(
                "Receiving servers refused {} of the {} messages this server forwarded in the last 24 hours, all of them from {}. To protect this server's mail reputation, K2 paused that mailbox's outside forwards; other mailboxes keep forwarding. New mail stays in the mailbox. Resume: k2 hostmail forward resume {}.",
                c.refused(),
                c.queued,
                f.address,
                f.address
            ),
            &[],
        );
    }
    paused
}

/// Pause through the sync (the Sieve goes keep-only) and file the notice.
/// `true` when the row moved (a deferred Sieve write is retried by the
/// hourly reconcile; the row is the truth).
fn pause_and_tell(f: &Forward, reason: &'static str, detail: serde_json::Value, note: Option<(String, String)>) -> bool {
    let moved = match forward_sync::pause(&f.id, reason, forward_sync::ACTOR_K2, Some(detail)) {
        Ok(_) => true,
        Err(forward_sync::ChangeError::Sieve(row, _)) => {
            k2_core::log_debug!("{P} forward {} paused ({reason}); its Sieve write is deferred to the reconcile", row.id);
            true
        }
        Err(forward_sync::ChangeError::Row(e)) => {
            k2_core::log_debug!("{P} WARN forward {} not paused ({reason}): {e}", f.id);
            false
        }
    };
    if moved {
        k2_core::log_debug!("{P} forward {} paused: {reason}", f.id);
        if let Some((title, body)) = note {
            let person = {
                let db = k2_core::db::shared();
                let conn = db.lock();
                store::person_principal(&conn, &f.address_id).ok().flatten()
            };
            let extra: Vec<String> = person.into_iter().filter(|p| p != k2_core::notify_prefs::OWNER).collect();
            super::forward_verify::tell_owner(&title, &body, &extra);
        }
    }
    moved
}

/// The notice for one forward's pause: (title, body).
pub fn notice_for(f: &Forward, reason: &str, c: &Counts, in_a_row: i64) -> (String, String) {
    let (addr, dest) = (&f.address, &f.dest);
    let resume = format!(
        "Resume it when that's fixed: k2 hostmail forward resume {addr} --to {dest} (the mailbox's person can use k2 mail forward resume). \
         Or stop forwarding there: k2 hostmail forward rm {addr} --to {dest}."
    );
    let stays = format!("New mail stays in {addr}; nothing is lost.");
    let title = format!("Forwarding from {addr} is paused");
    let body = match reason {
        r if r == store::P_DEST_GONE && in_a_row >= store::DEST_GONE_IN_A_ROW => format!(
            "K2 paused forwarding from {addr} to {dest}: the receiving server said {dest} doesn't exist or is disabled, \
             {in_a_row} times in a row. {stays}\n\nCheck the address with whoever owns it. {resume}"
        ),
        r if r == store::P_DEST_GONE => format!(
            "K2 paused forwarding from {addr} to {dest}: the receiving server said {dest} doesn't exist or is disabled \
             for {} of the {} messages forwarded in the last 24 hours. {stays}\n\nCheck the address with whoever owns it. {resume}",
            c.refused_user, c.queued
        ),
        r if r == store::P_REFUSED => format!(
            "K2 paused forwarding from {addr} to {dest}: the receiving server refused {} of the {} messages forwarded in the \
             last 24 hours as spam or against its policy (more than {}%). Forwarding more of them would hurt this server's \
             mail reputation. {stays}\n\nThe bounce reports in {addr} say why. {resume}",
            c.refused_policy,
            c.queued,
            store::REFUSED_PCT
        ),
        r if r == store::P_DAILY_CAP => format!(
            "K2 paused forwarding from {addr} to {dest}: it forwarded {} messages in the last 24 hours, the daily limit of {}. \
             {stays}\n\nIf that much mail is expected, resume it: k2 hostmail forward resume {addr}. If it isn't, check what is \
             arriving in {addr} before you resume.",
            c.queued,
            store::DAILY_CAP
        ),
        other => format!("K2 paused forwarding from {addr} to {dest} ({other}). {stays}\n\n{resume}"),
    };
    (title, body)
}

#[cfg(test)]
thread_local! {
    static NOTICES: std::cell::RefCell<Vec<(String, String, Vec<String>)>> = const { std::cell::RefCell::new(Vec::new()) };
}

/// Tests: the notices filed on this thread (taken).
#[cfg(test)]
pub(crate) fn take_notices() -> Vec<(String, String, Vec<String>)> {
    NOTICES.with(|n| std::mem::take(&mut *n.borrow_mut()))
}

#[cfg(test)]
thread_local! {
    static NOTICE_FAILS: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// Tests: make filing a notice fail on this thread.
#[cfg(test)]
pub(crate) fn set_notice_fails(fails: bool) {
    NOTICE_FAILS.with(|c| c.set(fails));
}

pub(crate) fn notice(title: &str, body: &str, extra: &[String]) {
    if let Err(e) = try_notice(title, body, extra) {
        k2_core::log_debug!("{P} WARN owner notice: {}", crate::email_notify::send::mask_addresses(&e));
    }
}

/// [`notice`], for a caller that has to know it was filed.
pub(crate) fn try_notice(title: &str, body: &str, extra: &[String]) -> Result<(), String> {
    #[cfg(test)]
    {
        if NOTICE_FAILS.with(std::cell::Cell::get) {
            return Err("fake: the Inbox refused".to_string());
        }
        NOTICES.with(|n| n.borrow_mut().push((title.to_string(), body.to_string(), extra.to_vec())));
        Ok(())
    }
    #[cfg(not(test))]
    {
        let r = if extra.is_empty() {
            crate::feedback_routes::file_owner_notice(k2_core::db::AUDIT_SENTINEL_IDS[0], "k2-email", title, body)
        } else {
            crate::feedback_routes::file_people_notice(k2_core::db::AUDIT_SENTINEL_IDS[0], "k2-email", title, body, extra)
        };
        r.map(|_| ()).map_err(|e| e.to_string())
    }
}

// ── is the webhook working? ─────────────────────────────────────────

/// Record whether delivery outcomes reach K2, and tell the owner when that
/// changes while outside forwards rely on it: with none, `dest_gone`, `refused`,
/// `daily_cap` and the box brake can't fire (the hourly throttles still hold).
pub fn webhook_health(error: Option<&str>) {
    let wanted = webhook_wanted();
    // An error with no outside forward relying on it isn't news yet: left
    // unrecorded, the owner hears when one does (the webhook runs for it).
    if error.is_some() && !wanted {
        return;
    }
    let changed = {
        let db = k2_core::db::shared();
        let conn = db.lock();
        store::set_webhook_error(&conn, error).unwrap_or(false)
    };
    if !changed || !wanted {
        return;
    }
    match error {
        Some(e) => super::forward_verify::tell_owner(
            "K2 can't see what happens to forwarded mail",
            &format!(
                "K2 couldn't set up the delivery reports from this server's mail server ({e}), so it can't see bounces or refusals. Until that's fixed, a forward won't pause by itself when its destination refuses mail, and the daily limit won't count. K2 keeps trying hourly. Check: k2 hostmail doctor."
            ),
            &[],
        ),
        None => super::forward_verify::tell_owner("K2 can see forwarded mail's delivery again", "The delivery reports from this server's mail server work again, so forwards pause by themselves when they should.", &[]),
    }
}

// ── after a forward change ──────────────────────────────────────────

/// Called after every forward change (`forward_sync::change_and_sync`,
/// outside its lock): an outside forward keeps the webhook on (or lets it
/// go when it was the last), and one activated while the brake holds is
/// paused with the rest.
pub fn after_change(row: &Forward) {
    if !row.is_external() {
        return;
    }
    // A pause never changes whether the webhook is wanted (the row stays live).
    if row.state != store::ST_PAUSED {
        crate::email_notify::webhook::spawn_after("forward");
    }
    if row.is_active() && !IN_EVAL.with(|c| c.get()) {
        let _ = evaluate_box(forward_sync::ctx().now);
    }
}

